<script setup lang="ts">
import { computed, onBeforeUnmount, onMounted, reactive, ref } from 'vue'
import { message, Modal } from 'ant-design-vue'
import { download, get, post } from '../api'
import { hasPermission } from '../auth'
import type { PageData } from '../types'
interface ReportRow { id:number; periodStart:string; status:string; created:number; completedAt?:number; filename?:string; lastError?:string }
const rows = ref<ReportRow[]>([]); const total = ref(0); const loading = ref(false); const month = ref(''); const query = reactive({page:1,perPage:20}); let timer:number|undefined
const maxMonth = computed(() => { const date = new Date(); date.setMonth(date.getMonth()-1); return `${date.getFullYear()}-${String(date.getMonth()+1).padStart(2,'0')}` })
async function load() { loading.value=true; try { const data=await get<PageData<ReportRow>>(`/billing/reports?page=${query.page}&perPage=${query.perPage}`); rows.value=data.rows||[]; total.value=data.count||0 } finally { loading.value=false } }
async function generate() { if (!month.value) return; await post(`/billing/reports/monthly?month=${month.value}`); message.success('报告已进入队列，完成后将通过通知中心提醒。'); load() }
function replay(row:ReportRow) { Modal.confirm({title:'人工重试报告',content:`确认重试 ${row.periodStart.slice(0,7)} 报告？`,async onOk(){await post(`/admin/reports/${row.id}/replay`);message.success('报告已重新入队');load()}}) }
const statusColor:Record<string,string>={QUEUED:'default',RUNNING:'blue',RETRY_WAIT:'gold',COMPLETED:'green',DEAD:'red'}
onMounted(()=>{load();timer=window.setInterval(load,10000)});onBeforeUnmount(()=>window.clearInterval(timer))
</script>
<template><div class="page-container"><div class="page-heading"><div><span class="eyebrow blue">Usage reports</span><h1>月度报告</h1><p>异步生成已结束自然月的用量、额度与费用报告。</p></div></div><section v-if="hasPermission('REPORT_GENERATE')" class="form-card inline-form"><a-space><a-input v-model:value="month" type="month" :max="maxMonth" style="width:200px" /><a-button type="primary" :disabled="!month" @click="generate">排队生成</a-button><span class="muted">只能选择已结束的自然月</span></a-space></section><div class="table-card top-gap-lg"><a-table :data-source="rows" :loading="loading" row-key="id" :pagination="{current:query.page,pageSize:query.perPage,total}"><a-table-column title="月份" key="month"><template #default="{record}">{{ record.periodStart?.slice(0,7) }}</template></a-table-column><a-table-column title="状态" key="status"><template #default="{record}"><a-tag :color="statusColor[record.status]">{{ record.status }}</a-tag></template></a-table-column><a-table-column title="提交时间" key="created"><template #default="{record}">{{ new Date(record.created*1000).toLocaleString() }}</template></a-table-column><a-table-column title="完成时间" key="completed"><template #default="{record}">{{ record.completedAt ? new Date(record.completedAt*1000).toLocaleString() : '—' }}</template></a-table-column><a-table-column title="操作" key="actions"><template #default="{record}"><a-button v-if="record.status==='COMPLETED'" type="link" @click="download(`/billing/reports/${record.id}/download`,record.filename)">下载</a-button><a-button v-if="record.status==='DEAD' && hasPermission('REPORT_MANAGE')" type="link" danger @click="replay(record)">人工重试</a-button><span v-if="!['COMPLETED','DEAD'].includes(record.status)" class="muted">查看状态</span></template></a-table-column></a-table></div></div></template>
